import{_ as n,o as i,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Running Ceph on Flashcache - Paweł Sadowski","description":"","frontmatter":{"title":"Running Ceph on Flashcache - Paweł Sadowski","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["Ceph","Flashcache","Distributed Storage","Optimization","Storage Performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Running_Ceph_on_Flashcache_-_Pawe_Sadowski.md","filePath":"posts/2018/Running_Ceph_on_Flashcache_-_Pawe_Sadowski.md","lastUpdated":1780459816000}'),l={name:"posts/2018/Running_Ceph_on_Flashcache_-_Pawe_Sadowski.md"};function e(a,t,r,p,g,h){return i(),s("div",null,[...t[0]||(t[0]=[o('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未知）</p><p><strong>与会人员</strong>： Prabhav Sikka（OVH DevOps工程师），其他与会者姓名未提及</p><p><strong>会议主题</strong>： Ceph分布式存储在OVH的使用经验及优化方案</p><p><strong>关键细节</strong>：</p><ul><li>OVH使用Ceph作为其托管服务的一部分，拥有约150个集群，运行在1150台服务器上，存储容量约为44PB，使用2PB NVMe和超过70,000个SSD实例。</li><li>Prabhav Sikka分享了他们在使用Ceph过程中遇到的问题及解决方案。</li></ul><p><strong>讨论的主要议题及决定的事项</strong>：</p><p><strong>议题一：缓存优化</strong></p><ul><li><strong>问题</strong>： Ceph在执行深度清理等操作时，会读取所有数据填充缓存，导致缓存数据无效，影响性能。</li><li><strong>解决方案</strong>： <ul><li>使用PID黑名单功能，允许禁用特定I/O的缓存。</li><li>使用跳过顺序阈值，跳过对大块连续读写的缓存。</li></ul></li><li><strong>决定</strong>： 推进PID黑名单功能的开发，并测试跳过顺序阈值的效果。</li></ul><p><strong>议题二：块大小匹配</strong></p><ul><li><strong>问题</strong>： 客户端在执行快照操作时，由于未删除快照，导致大量数据需要保存到X属性中，影响性能。</li><li><strong>解决方案</strong>： 修改Ceph配置，使块大小与存储层匹配，减少数据转换和冲突。</li><li><strong>决定</strong>： 将此解决方案合并到Ceph文档中。</li></ul><p><strong>议题三：平缓曲线死锁</strong></p><ul><li><strong>问题</strong>： 部分服务器出现随机冻结现象，导致I/O阻塞。</li><li><strong>解决方案</strong>： 分析内核数据，发现死锁问题，并在XFS中修复。</li><li><strong>决定</strong>： 将修复后的XFS版本部署到服务器上。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续测试和优化Ceph性能。</li><li>推进PID黑名单功能的开发。</li><li>跟进跳过顺序阈值的效果。</li><li>部署修复后的XFS版本。</li><li>探索Ceph与其他存储技术的结合方案。</li></ul><p><strong>其他事项</strong>：</p><ul><li>OVH正在寻找Buster的替代方案，并正在测试Intel Ceph加速软件。</li><li>Prabhav Sikka认为Ceph是一个功能强大且值得信赖的存储解决方案。</li></ul><p><strong>改进说明</strong>：</p><ul><li>确保了会议纪要准确反映了原始内容的要点，包括关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li><li>原始字幕内容中的错误、误解或遗漏的重要信息已通过优化后的总结得到体现。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词，如Ceph、Flashcache、distributed storage、optimization等。</li></ul>',20)])])}const u=n(l,[["render",e]]);export{c as __pageData,u as default};
